/**
 * Rendering of CPython tracebacks.
 *
 * Library modules raise `PyException`s carrying only their own internal frames;
 * the entry point prepends the `test8.py` call-site frame before printing, which
 * mirrors how a real traceback is assembled as the exception unwinds.
 */

/** One `File "...", line N, in name` entry, optionally with a source echo. */
export class Frame {
  constructor(file, line, name, source = null, caret = null) {
    this.file = file;
    this.line = line;
    this.name = name;
    this.source = source;
    this.caret = caret;
  }

  render() {
    const lines = [`  File "${this.file}", line ${this.line}, in ${this.name}`];
    if (this.source !== null) lines.push(`    ${this.source}`);
    if (this.caret !== null) lines.push(`    ${this.caret}`);
    return lines;
  }
}

/**
 * An exception that knows how to reproduce its Python traceback.
 * `header` is the terminating `module.ExcType: message` line.
 */
export class PyException extends Error {
  constructor(header, frames = []) {
    super(header);
    this.name = 'PyException';
    this.header = header;
    this.frames = frames;
  }

  /** Returns a copy with `frames` pushed in front of the existing ones. */
  withOuterFrames(frames) {
    const copy = new PyException(this.header, [...frames, ...this.frames]);
    Object.setPrototypeOf(copy, Object.getPrototypeOf(this));
    return copy;
  }

  formatTraceback() {
    const out = ['Traceback (most recent call last):'];
    for (const frame of this.frames) out.push(...frame.render());
    out.push(this.header);
    return out.join('\n') + '\n';
  }
}

/**
 * Builds the caret underline CPython 3.11+ draws beneath the failing
 * sub-expression of a source line: spaces up to `start`, then one `^` per
 * character of the expression.
 */
export function caretFor(source, expression) {
  const start = source.indexOf(expression);
  return ' '.repeat(start) + '^'.repeat(expression.length);
}

export function pyTypeError(message, frames) {
  return new PyException(`TypeError: ${message}`, frames);
}

export function pyAttributeError(message, frames) {
  return new PyException(`AttributeError: ${message}`, frames);
}

