/**
 * `json.decoder.JSONDecodeError`, including CPython's position arithmetic.
 */
import { Frame, PyException } from '../python/traceback.mjs';

/** Frames for `json.loads` -> `JSONDecoder.decode`. */
const LOADS_FRAME = new Frame('json/__init__.py', 346, 'loads');

/**
 * CPython's json module is backed by the C scanner, so nested parse failures
 * surface at one of only three places:
 *
 *  - "Extra data" is raised by `decode` itself, after `raw_decode` returned.
 *  - "Expecting value" always arrives as a `StopIteration` from the C scanner
 *    and is converted to a JSONDecodeError by `raw_decode`.
 *  - every other message is raised from inside the C scan_once call.
 */
function decoderFrames(message) {
  if (message === 'Extra data') {
    return [LOADS_FRAME, new Frame('json/decoder.py', 340, 'decode')];
  }
  const inner = message === 'Expecting value' ? 355 : 353;
  return [
    LOADS_FRAME,
    new Frame('json/decoder.py', 337, 'decode'),
    new Frame('json/decoder.py', inner, 'raw_decode'),
  ];
}

/**
 * Mirrors `JSONDecodeError.__init__`: the human-readable message embeds a
 * 1-based line number and a column measured from the last newline.
 */
export class JSONDecodeError extends PyException {
  constructor(message, doc, pos) {
    const lineno = countNewlines(doc, pos) + 1;
    const colno = pos - doc.lastIndexOf('\n', pos - 1);
    const detail = `${message}: line ${lineno} column ${colno} (char ${pos})`;
    super(`json.decoder.JSONDecodeError: ${detail}`, decoderFrames(message));
    this.msg = message;
    this.doc = doc;
    this.pos = pos;
  }
}

function countNewlines(doc, end) {
  let count = 0;
  for (let i = 0; i < end; i += 1) {
    if (doc[i] === '\n') count += 1;
  }
  return count;
}

/**
 * The C scanner's `raise_stop_iteration`: "there is no value here". Carries the
 * offset so `raw_decode` can turn it into an "Expecting value" error.
 */
export class StopIteration {
  constructor(pos) {
    this.pos = pos;
  }
}

