/**
 * A re-implementation of CPython's `json.loads` that reproduces both the values
 * and the diagnostics of the C scanner (`_json.make_scanner`).
 *
 * Two behaviours matter here beyond plain `JSON.parse`:
 *   - `NaN`, `Infinity` and `-Infinity` are accepted, as CPython accepts them;
 *   - failures carry CPython's exact message, offset and traceback shape.
 */
import { JSONDecodeError, StopIteration } from './errors.mjs';
import { pyFloat, pyInt } from '../python/values.mjs';

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

const ESCAPES = {
  '"': '"',
  '\\': '\\',
  '/': '/',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
};

/** CPython's `json.decoder.NUMBER_RE`, anchored at the scan position. */
const NUMBER_RE = /(-?(?:0|[1-9]\d*))(\.\d+)?([eE][-+]?\d+)?/y;

function skipWhitespace(s, idx) {
  let i = idx;
  while (i < s.length && WHITESPACE.has(s[i])) i += 1;
  return i;
}

function isHexDigit(ch) {
  return /^[0-9a-fA-F]$/.test(ch);
}

/**
 * `scanstring`. `end` is the offset just after the opening quote; the returned
 * `end` is the offset just after the closing quote.
 */
function scanString(s, end) {
  const begin = end - 1;
  let out = '';
  let next = end;

  for (;;) {
    let i = next;
    while (i < s.length) {
      const ch = s[i];
      if (ch === '"' || ch === '\\') break;
      // strict=True: raw control characters are rejected inside strings.
      if (ch.charCodeAt(0) <= 0x1f) {
        throw new JSONDecodeError('Invalid control character at', s, i);
      }
      i += 1;
    }
    if (i >= s.length) {
      throw new JSONDecodeError('Unterminated string starting at', s, begin);
    }
    out += s.slice(next, i);

    if (s[i] === '"') return { value: out, end: i + 1 };

    // s[i] is a backslash; step onto the escape character.
    next = i + 1;
    if (next >= s.length) {
      throw new JSONDecodeError('Unterminated string starting at', s, begin);
    }
    const esc = s[next];

    if (esc !== 'u') {
      const mapped = ESCAPES[esc];
      if (mapped === undefined) {
        throw new JSONDecodeError('Invalid \\escape', s, next - 1);
      }
      out += mapped;
      next += 1;
      continue;
    }

    next += 1;
    if (next + 4 > s.length) {
      throw new JSONDecodeError('Invalid \\uXXXX escape', s, next - 1);
    }
    const digits = s.slice(next, next + 4);
    for (const digit of digits) {
      if (!isHexDigit(digit)) {
        throw new JSONDecodeError('Invalid \\uXXXX escape', s, next - 1);
      }
    }
    // Surrogate pairs need no special casing: appending the two code units
    // separately yields the same UTF-16 string Python builds as one code point.
    out += String.fromCharCode(parseInt(digits, 16));
    next += 4;
  }
}

function parseObject(s, start, scan) {
  // `Object.create(null)` keeps JSON keys such as `__proto__` from colliding
  // with prototype members, so key lookups stay faithful to a Python dict.
  const result = Object.create(null);
  let idx = skipWhitespace(s, start);

  if (idx >= s.length || s[idx] !== '}') {
    for (;;) {
      if (idx >= s.length || s[idx] !== '"') {
        throw new JSONDecodeError(
          'Expecting property name enclosed in double quotes',
          s,
          idx,
        );
      }
      const key = scanString(s, idx + 1);
      idx = skipWhitespace(s, key.end);

      if (idx >= s.length || s[idx] !== ':') {
        throw new JSONDecodeError("Expecting ':' delimiter", s, idx);
      }
      idx = skipWhitespace(s, idx + 1);

      const value = scan(s, idx);
      result[key.value] = value.value;
      idx = skipWhitespace(s, value.end);

      if (idx >= s.length) {
        throw new JSONDecodeError("Expecting ',' delimiter", s, idx);
      }
      if (s[idx] === '}') break;
      if (s[idx] !== ',') {
        throw new JSONDecodeError("Expecting ',' delimiter", s, idx);
      }
      idx = skipWhitespace(s, idx + 1);
    }
  }
  return { value: result, end: idx + 1 };
}

function parseArray(s, start, scan) {
  const values = [];
  let idx = skipWhitespace(s, start);

  if (idx >= s.length || s[idx] !== ']') {
    for (;;) {
      const value = scan(s, idx);
      values.push(value.value);
      idx = skipWhitespace(s, value.end);

      if (idx >= s.length) {
        throw new JSONDecodeError("Expecting ',' delimiter", s, idx);
      }
      if (s[idx] === ']') break;
      if (s[idx] !== ',') {
        throw new JSONDecodeError("Expecting ',' delimiter", s, idx);
      }
      idx = skipWhitespace(s, idx + 1);
    }
  }
  return { value: values, end: idx + 1 };
}

/**
 * `scan_once`. Throws `StopIteration` where the C scanner finds no value at all
 * — that is what later becomes "Expecting value".
 */
function scanOnce(s, idx) {
  if (idx >= s.length) throw new StopIteration(idx);

  const ch = s[idx];
  if (ch === '"') return scanString(s, idx + 1);
  if (ch === '{') return parseObject(s, idx + 1, scanOnce);
  if (ch === '[') return parseArray(s, idx + 1, scanOnce);
  if (ch === 'n' && s.startsWith('null', idx)) return { value: null, end: idx + 4 };
  if (ch === 't' && s.startsWith('true', idx)) return { value: true, end: idx + 4 };
  if (ch === 'f' && s.startsWith('false', idx)) return { value: false, end: idx + 5 };

  NUMBER_RE.lastIndex = idx;
  const m = NUMBER_RE.exec(s);
  if (m !== null && m[0].length > 0) {
    const [text, integer, frac, exp] = m;
    const value =
      frac || exp ? pyFloat(Number(text), text) : pyInt(Number(integer), integer);
    return { value, end: idx + text.length };
  }

  // Python's non-standard constants, accepted by default.
  if (ch === 'N' && s.startsWith('NaN', idx)) {
    return { value: pyFloat(NaN, 'NaN'), end: idx + 3 };
  }
  if (ch === 'I' && s.startsWith('Infinity', idx)) {
    return { value: pyFloat(Infinity, 'Infinity'), end: idx + 8 };
  }
  if (ch === '-' && s.startsWith('-Infinity', idx)) {
    return { value: pyFloat(-Infinity, '-Infinity'), end: idx + 9 };
  }

  throw new StopIteration(idx);
}

/** `json.loads` for a `str` argument. */
export function loads(s) {
  let result;
  try {
    result = scanOnce(s, skipWhitespace(s, 0));
  } catch (err) {
    if (err instanceof StopIteration) {
      throw new JSONDecodeError('Expecting value', s, err.pos);
    }
    throw err;
  }

  const end = skipWhitespace(s, result.end);
  if (end !== s.length) throw new JSONDecodeError('Extra data', s, end);
  return result.value;
}

