 * that each take exactly one value, `-h/--help`, prefix abbreviation, and the
 * error messages/exit codes CPython produces.
 */

/** `argparse._negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

