 * Thrown instead of calling `process.exit` directly, so that the entry point
 * owns all stream writes and exit codes.
 */
export class ParserExit extends Error {
  constructor(status, stdout = '', stderr = '') {
    super(`parser exit ${status}`);
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      dest: 'help',
      takesValue: false,
      help: HELP_TEXT,
    });
  }

  addArgument(optionStrings, options) {
    const action = new Action(optionStrings, options);
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

