    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.takesValue) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let afterSeparator = false;

    for (let i = 0; i < argv.length; i += 1) {
