const MAX_HELP_POSITION = 24;

class Action {
  constructor(optionStrings, { dest, required = false, help = '', takesValue = true }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required;
    this.help = help;
    this.takesValue = takesValue;
  }

  /** `_get_action_name`, used in `argument ...:` error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** How the action is listed in the options section, e.g. `--a A`. */
  get invocation() {
    if (!this.takesValue) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((opt) => `${opt} ${metavar}`).join(', ');
  }
