/**
 * `jsonschema._types.TypeChecker` and the draft 7 set of type checkers.
 */
import { UndefinedTypeCheck } from './exceptions.mjs';
import { PyNumber, isDict } from '../python/values.mjs';

/**
 * An immutable registry mapping JSON Schema type names to predicates, exposing
 * the `is_type(instance, type)` entry point.
 */
export class TypeChecker {
  constructor(typeCheckers = {}) {
    this._typeCheckers = new Map(Object.entries(typeCheckers));
  }

  /** The type names this checker recognises. */
  knownTypes() {
    return [...this._typeCheckers.keys()];
  }

  isType(instance, type) {
    const check = this._typeCheckers.get(type);
    if (check === undefined) throw new UndefinedTypeCheck(type);
    return check(this, instance);
  }
}

const isString = (_checker, instance) => typeof instance === 'string';
const isObject = (_checker, instance) => isDict(instance);
const isArray = (_checker, instance) => Array.isArray(instance);
const isNull = (_checker, instance) => instance === null;
// Draft 4 onwards, `boolean` is the only type a Python bool satisfies, so the
// numeric checkers have to exclude it explicitly.
const isBool = (_checker, instance) => typeof instance === 'boolean';
const isNumber = (_checker, instance) => instance instanceof PyNumber;
const isInteger = (_checker, instance) => instance instanceof PyNumber && instance.isInt;

/** `jsonschema._types.draft7_type_checker`. */
export const draft7TypeChecker = new TypeChecker({
  array: isArray,
  boolean: isBool,
  integer: isInteger,
  object: isObject,
  null: isNull,
  number: isNumber,
  string: isString,
});

