/**
 * The `referencing` behaviour that `Draft7Validator.__init__` triggers.
 *
 * Draft 7 resolves a resource's identifier with `_legacy_dollar_id`. That
 * function assumes the schema is either a bool or a mapping, so any other JSON
 * value raises — and *which* exception you get, at which source line, depends on
 * the value's Python type. Reproducing that is the whole job of this module.
 */
import { Frame, pyAttributeError, pyTypeError } from '../python/traceback.mjs';
import { containsSupported, isDict, pyContains, typeName } from '../python/values.mjs';

/** The `referencing` frames between `__attrs_post_init__` and the failure. */
const RESOLVER_FRAMES = [
  new Frame('referencing/_core.py', 590, 'resolver_with_root'),
  new Frame('referencing/_core.py', 231, 'id'),
];

function dollarIdFrames(line) {
  return [...RESOLVER_FRAMES, new Frame('referencing/jsonschema.py', line, '_legacy_dollar_id')];
}

/**
 * `referencing.jsonschema._legacy_dollar_id`, which reads roughly:
 *
 *     if isinstance(contents, bool):      return
 *     if "$ref" in contents:              return        # line 54
 *     id = contents.get("$id")                          # line 56
 *     if id is not None and not id.startswith("#"):     # line 57
 *         return id
 *
 * Returns the resolved `$id`, or null when there is none.
 */
export function legacyDollarId(contents) {
  if (typeof contents === 'boolean') return null;

  // line 54: `in` needs an iterable/container.
  if (!containsSupported(contents)) {
    return dollarIdRaise(
      pyTypeError(`argument of type '${typeName(contents)}' is not iterable`, dollarIdFrames(54)),
    );
  }
  // A str or list containing "$ref" satisfies `in` and returns here, escaping
  // the `.get` below only to fail later in `ignore_ref_siblings`.
  if (pyContains(contents, '$ref')) return null;

  // line 56: only a mapping has `.get`.
  if (!isDict(contents)) {
    return dollarIdRaise(
      pyAttributeError(
        `'${typeName(contents)}' object has no attribute 'get'`,
        dollarIdFrames(56),
      ),
    );
  }

  const id = Object.prototype.hasOwnProperty.call(contents, '$id') ? contents['$id'] : null;
  if (id === null) return null;

  // line 57: only a str has `.startswith`.
  if (typeof id !== 'string') {
    return dollarIdRaise(
      pyAttributeError(
        `'${typeName(id)}' object has no attribute 'startswith'`,
        dollarIdFrames(57),
      ),
    );
  }
  return id.startsWith('#') ? null : id;
}

function dollarIdRaise(exception) {
  throw exception;
}

/**
 * `jsonschema._legacy_keywords.ignore_ref_siblings`, the draft 7
 * `applicable_validators`. Its first statement is `schema.get("$ref")`, so a
 * non-mapping schema that got this far fails here instead.
 */
export function ignoreRefSiblings(schema) {
  if (!isDict(schema)) {
    throw pyAttributeError(`'${typeName(schema)}' object has no attribute 'get'`, [
      new Frame('jsonschema/_legacy_keywords.py', 17, 'ignore_ref_siblings'),
    ]);
  }
  const ref = Object.prototype.hasOwnProperty.call(schema, '$ref') ? schema['$ref'] : null;
  return ref === null ? Object.entries(schema) : [['$ref', ref]];
}

