/**
 * The part of `linecache` that tracebacks depend on.
 *
 * A frozen build records the *relative* filename `test8.py`, so CPython echoes
 * the offending source line only when a file of that name happens to be
 * resolvable from the current working directory — and omits the echo (and its
 * caret line) otherwise. Reproducing that keeps stderr identical no matter where
 * the program is run from.
 */
import { readFileSync } from 'node:fs';

const cache = new Map();

function getLines(filename) {
  if (cache.has(filename)) return cache.get(filename);
  let lines = null;
  try {
    lines = readFileSync(filename, 'utf8').split('\n');
  } catch {
    lines = null;
  }
  cache.set(filename, lines);
  return lines;
}

/** `linecache.getline`: the 1-based line, or '' when it cannot be read. */
export function getline(filename, lineno) {
  const lines = getLines(filename);
  if (lines === null || lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

