/**
 * A small stand-in for the slice of `argparse` this program uses: long options
 * that each take exactly one value, `-h/--help`, prefix abbreviation, and the
 * error messages/exit codes CPython produces.
 */

/** `argparse._negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const PREFIX_CHARS = new Set(['-']);
const HELP_TEXT = 'show this help message and exit';
const MAX_HELP_POSITION = 24;

class Action {
  constructor(optionStrings, { dest, required = false, help = '', takesValue = true }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required;
    this.help = help;
    this.takesValue = takesValue;
  }

  /** `_get_action_name`, used in `argument ...:` error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** How the action is listed in the options section, e.g. `--a A`. */
  get invocation() {
    if (!this.takesValue) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((opt) => `${opt} ${metavar}`).join(', ');
  }
}

/**
 * Thrown instead of calling `process.exit` directly, so that the entry point
 * owns all stream writes and exit codes.
 */
export class ParserExit extends Error {
  constructor(status, stdout = '', stderr = '') {
    super(`parser exit ${status}`);
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      dest: 'help',
      takesValue: false,
      help: HELP_TEXT,
    });
  }

  addArgument(optionStrings, options) {
    const action = new Action(optionStrings, options);
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation = action.takesValue
        ? `${action.optionStrings[0]} ${action.dest.toUpperCase()}`
        : action.optionStrings[0];
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at `min(max_action_length + 2, 24)`, where the
    // action length already includes the two-space section indent.
    const maxInvocation = Math.max(...this.actions.map((a) => a.invocation.length));
    const helpPosition = Math.min(maxInvocation + 2 + 2, MAX_HELP_POSITION);

    const out = [this.formatUsage(), '\n', 'options:\n'];
    for (const action of this.actions) {
      const head = `  ${action.invocation}`;
      if (head.length < helpPosition) {
        out.push(`${head.padEnd(helpPosition)}${action.help}\n`);
      } else {
        out.push(`${head}\n${' '.repeat(helpPosition)}${action.help}\n`);
      }
    }
    return out.join('');
  }

  /** `parser.error`: usage plus message on stderr, exit status 2. */
  error(message) {
    throw new ParserExit(2, '', `${this.formatUsage()}${this.prog}: error: ${message}\n`);
  }

  /**
   * `_parse_optional`. Returns null when the token should be treated as a plain
   * value, or a descriptor whose `action` is null for an unknown option. `sep`
   * records whether the value was attached with `=`, which changes how a
   * zero-argument action reacts.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.has(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return {
        action: this.optionStringActions.get(argString),
        optionString: argString,
        sep: '',
        explicitArg: null,
      };
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          sep: '=',
          explicitArg: argString.slice(eq + 1),
        };
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map((m) => m.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    // A bare negative number is a value, since no option looks like one.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: '', explicitArg: null };
  }

  /** `_get_option_tuples`: abbreviation matching. */
  getOptionTuples(argString) {
    const matches = [];

    if (PREFIX_CHARS.has(argString[1])) {
      let prefix = argString;
      let sep = '';
      let explicitArg = null;
      const eq = argString.indexOf('=');
      if (eq !== -1) {
        prefix = argString.slice(0, eq);
        sep = '=';
        explicitArg = argString.slice(eq + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          matches.push({ action, optionString, sep, explicitArg });
        }
      }
      return matches;
    }

    // Single dash: either an abbreviation, or a short option with its value
    // bundled directly onto it.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        matches.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        matches.push({ action, optionString, sep: '', explicitArg: null });
      }
    }
    return matches;
  }

  /**
   * Handles an option that takes no value. CPython only tolerates an attached
   * argument when it looks like bundled short options (`-hx`); anything else,
   * including `--help=x` and `--help=`, is an error.
   */
  consumeFlag(action, { sep, explicitArg }) {
    if (explicitArg !== null) {
      const bundled = sep === '' && explicitArg !== '' && !PREFIX_CHARS.has(explicitArg[0]);
      if (!bundled) {
        this.error(`argument ${action.name}: ignored explicit argument '${explicitArg}'`);
      }
    }
    throw new ParserExit(0, this.formatHelp(), '');
  }

  parseArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.takesValue) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let afterSeparator = false;

    for (let i = 0; i < argv.length; i += 1) {
      const arg = argv[i];

      // Everything from the first `--` onwards is positional. With no
      // positionals declared, that means it all ends up unrecognized.
      if (afterSeparator) {
        extras.push(arg);
        continue;
      }
      if (arg === '--') {
        afterSeparator = true;
        extras.push(arg);
        continue;
      }

      const option = this.parseOptional(arg);
      if (option === null || option.action === null) {
        extras.push(arg);
        continue;
