        this.consumeFlag(action, option);
      }

      let value = option.explicitArg;
      if (value === null) {
        const next = i + 1 < argv.length ? argv[i + 1] : null;
        if (next === null || this.parseOptional(next) !== null) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        value = next;
        i += 1;
      }

      namespace[action.dest] = value;
      seen.add(action);
    }

    // argparse checks required arguments before reporting leftovers.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

