#!/usr/bin/env node
/**
 * Node.js port of test8.py:
 *
 *   schema = json.loads(args.a)
 *   validator = Draft7Validator(schema)
 *   type_checker = validator.TYPE_CHECKER
 *   result = type_checker.is_type(args.b, args.b)
 *   print(result)
 *
 * `is_type(args.b, args.b)` asks whether the *string* `--b` is an instance of
 * the type named by `--b`, so the only draft 7 type that answers True is
 * "string"; the other six answer False and anything else raises
 * UndefinedTypeCheck.
 */
import process from 'node:process';

import { ArgumentParser, ParserExit } from './lib/python/argparse.mjs';
import { Frame, PyException, caretFor } from './lib/python/traceback.mjs';
import { pyBoolRepr } from './lib/python/values.mjs';
import { loads } from './lib/pyjson/decoder.mjs';
import { Draft7Validator } from './lib/jsonschema/validators.mjs';

// argparse takes the program name from argv[0]; for the reference build that is
// the frozen executable, so usage/help text says `test8_executable`.
const PROG = 'test8_executable';

/** A `<module>`-level frame for one of test8.py's statements. */
function site(line, source, expression) {
  return new Frame('test8.py', line, '<module>', source, caretFor(source, expression));
}

const SITES = {
  loads: site(11, 'schema = json.loads(args.a)', 'json.loads(args.a)'),
  validator: site(
    13,
    'validator = Draft7Validator(schema)  # Create validator',
    'Draft7Validator(schema)',
  ),
  isType: site(
    15,
    'result = type_checker.is_type(args.b, args.b)  # Check if type exists',
    'type_checker.is_type(args.b, args.b)',
  ),
};

function buildParser() {
  const parser = new ArgumentParser(PROG);
  parser.addArgument(['--a'], { dest: 'a', required: true, help: 'schema (JSON string)' });
  parser.addArgument(['--b'], { dest: 'b', required: true, help: 'type name' });
  return parser;
}

/** Tags an exception with the test8.py line that raised it. */
function at(err, frame) {
  return err instanceof PyException ? err.withOuterFrames([frame]) : err;
}

function main(argv) {
  const args = buildParser().parseArgs(argv);

  let schema;
  try {
    schema = loads(args.a);
  } catch (err) {
    throw at(err, SITES.loads);
  }

  let validator;
  try {
    validator = new Draft7Validator(schema);
  } catch (err) {
    throw at(err, SITES.validator);
  }

  const typeChecker = validator.TYPE_CHECKER;

  let result;
  try {
    result = typeChecker.isType(args.b, args.b);
  } catch (err) {
    throw at(err, SITES.isType);
  }

  process.stdout.write(`${pyBoolRepr(result)}\n`);
}

try {
  main(process.argv.slice(2));
} catch (err) {
  if (err instanceof ParserExit) {
    if (err.stdout !== '') process.stdout.write(err.stdout);
    if (err.stderr !== '') process.stderr.write(err.stderr);
    process.exitCode = err.status;
  } else if (err instanceof PyException) {
    // An unhandled Python exception: traceback on stderr, exit status 1.
    process.stderr.write(err.formatTraceback());
    process.exitCode = 1;
  } else {
    throw err;
  }
}

