/** Python's `bool` repr, which is what `print(True)` writes. */
export function pyBoolRepr(value) {
  return value ? 'True' : 'False';
}

/**
 * `str.isprintable()`: false for the Unicode "Other" categories and for
 * separators other than a plain ASCII space.
 */
function isPrintable(codePoint) {
  const ch = String.fromCodePoint(codePoint);
  if (ch === ' ') return true;
  return !/\p{C}|\p{Z}/u.test(ch);
}

const SHORT_ESCAPES = { '\t': '\\t', '\n': '\\n', '\r': '\\r', '\\': '\\\\' };

/**
 * `repr()` of a Python `str`. Single quotes are preferred, but a string that
 * contains an apostrophe and no double quote is wrapped in double quotes
 * instead; unprintable characters become \xXX, \uXXXX or \UXXXXXXXX escapes.
 */
export function pyStrRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of value) {
    if (ch === quote) {
      out += `\\${ch}`;
    } else if (SHORT_ESCAPES[ch] !== undefined) {
      out += SHORT_ESCAPES[ch];
    } else {
      const cp = ch.codePointAt(0);
      if (isPrintable(cp)) {
        out += ch;
      } else if (cp < 0x100) {
        out += `\\x${cp.toString(16).padStart(2, '0')}`;
      } else if (cp < 0x10000) {
        out += `\\u${cp.toString(16).padStart(4, '0')}`;
      } else {
        out += `\\U${cp.toString(16).padStart(8, '0')}`;
      }
    }
  }
  return out + quote;
}

