/**
 * Minimal model of the Python values that `json.loads` can produce.
 *
 * JavaScript has a single numeric type, but CPython distinguishes `int` from
 * `float` and that distinction leaks into the error messages this program can
 * emit (e.g. "argument of type 'int' is not iterable" vs "... 'float' ...").
 * Numbers are therefore boxed in `PyNumber`, which remembers which of the two
 * Python types the literal decoded to. Every other JSON value maps onto a
 * native JS value.
 */

/** A decoded JSON number, tagged with the Python type it became. */
export class PyNumber {
  constructor(value, isInt, raw) {
    this.value = value;
    this.isInt = isInt;
    this.raw = raw;
  }
}

export function pyInt(value, raw) {
  return new PyNumber(value, true, raw);
}

export function pyFloat(value, raw) {
  return new PyNumber(value, false, raw);
}

/**
 * The name CPython uses for a value's type, as it appears in messages such as
 * `AttributeError: 'str' object has no attribute 'get'`.
 */
export function typeName(value) {
  if (value === null) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'string') return 'str';
  if (value instanceof PyNumber) return value.isInt ? 'int' : 'float';
  if (Array.isArray(value)) return 'list';
  return 'dict';
}

/** Python's `bool` repr, which is what `print(True)` writes. */
export function pyBoolRepr(value) {
  return value ? 'True' : 'False';
}

/**
 * Python's `in` operator, restricted to the container kinds a JSON document
 * can hold. On `str` it is a substring test, on `list` a membership test and
 * on `dict` a key test; on anything else CPython raises TypeError, which the
 * caller signals by way of `containsSupported`.
 */
export function containsSupported(container) {
  return (
    typeof container === 'string' ||
    Array.isArray(container) ||
    (container !== null && typeof container === 'object' && !(container instanceof PyNumber))
  );
}

export function pyContains(container, needle) {
  if (typeof container === 'string') return container.includes(needle);
  if (Array.isArray(container)) return container.includes(needle);
  return Object.prototype.hasOwnProperty.call(container, needle);
}

/** True only for the JSON values that behave like a Python `dict`. */
export function isDict(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    !(value instanceof PyNumber)
  );
}

