#!/usr/bin/env node
/**
 * Randomized differential fuzzing, focused on the JSON decoder (where the
 * message/offset arithmetic is most intricate) and on argv shapes.
 */
import { spawnSync } from 'node:child_process';
import process from 'node:process';

const REF = '/workspace/dataset/test8_executable';
const PORT = '/output/test8.mjs';
const PYI_LINE = /^\[PYI-\d+:ERROR\].*\n?/m;

const ROUNDS = Number(process.argv[2] ?? 400);

let seed = 0x2f6e2b1;
function rand(n) {
  // xorshift32, so failures are reproducible from the seed above.
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  seed >>>= 0;
  return seed % n;
}

